@classmethod
def references(cls, root: Path, registry: Registration, log: WireLog, references: Sequence[MessageReference]) -> dict[tuple[int, str], tuple[MessageNotification, ...]]:
    """Borrow mounted references in the original bounded delivery windows."""
    from .notification_assignment import NotificationAssignment
    return cls.read_references(log, references, lambda sources: cls.delivery_window(root, registry, sources, NotificationAssignment.read(root, sources)))

@classmethod
def capture(cls, snapshot: RegistrySnapshot, catalog: CatalogDocument, reads: ReadLedger, document: ReadDocument, viewer: str | None) -> DisplaySelection:
    canonical = snapshot.canonical_name(viewer) if viewer is not None else None
    seen = reads.seen_sequences(viewer, snapshot, document=document) if viewer is not None else frozenset()
    return cls(snapshot, catalog, canonical, seen, document)

@classmethod
def capture(cls, root: Path, registry: RegistrySnapshot, catalog: CatalogDocument, agents: AgentActivity, declarations: Mapping[str, Channel], sent: Mapping[str, float], messages: Mapping[str, ChannelActivity], *, unread: Mapping[str, int], channel_unread: Mapping[str, int], show_stopped: bool, show_archived: bool, read_marker_notice: str | None=None) -> CoordinationSnapshot:
    """Assemble both rosters from the caller's acquired identity and read cut."""
    threads = OrderedDict(((view.thread.name, view) for view in ThreadView.roster(registry, agents, GoalWaits(root / GoalWaits.filename), show_stopped=show_stopped, show_archived=show_archived)))
    activities = {name: view.activity for name, view in threads.items()}
    return cls(channels=OrderedDict(((view.channel.name, view) for view in ChannelView.roster(registry, declarations, catalog.pinned_members(), catalog.list_order, activities, sent, messages, show_stopped=show_stopped, show_archived=show_archived))), threads=threads, unread=unread, last_sent=sent, channel_unread=channel_unread, references=DisplayReferences.capture(root, registry, declarations), channel_order=catalog.list_order, show_stopped=show_stopped, show_archived=show_archived, read_marker_notice=read_marker_notice)

@classmethod
def capture(cls, views: HistoryViews, *, expiry_tick: int) -> WireRevision:
    """Every source is a group; missing files contribute no revision."""
    paths = cls.source_paths(views)
    with _store_read_lock(views.bus.log.path) as source:
        through_seq = views.bus.log._committed_sequence_unlocked(source)
        captured = {name: tuple((revision for path in group if (revision := FileRevision.capture(path)) is not None)) for name, group in paths.items()}
    return cls(**captured, expiry_tick=expiry_tick, through_seq=through_seq)

async def pass_on_unread(self, turns: TurnRunner) -> None:
    """Inputs the ended turn never read start the next turn or are refused, never replayed."""
    while not self.inbox.empty():
        for carried in self.inbox.get_nowait().carried_inputs:
            if await self.pass_on(turns, carried.value):
                return

def bind(self, sessions: SessionLifecycle, inputs: InputDrain) -> None:
    self.sessions = sessions
    self.inputs = inputs

def write(self, record: Checkpoint) -> None:
    payload = json.dumps(self._encode(record))
    with _store_lock(self.path):
        try:
            stream = self.source_path.open('rb')
        except FileNotFoundError:
            return
        with stream:
            current = FileRevision.from_stat(os.fstat(stream.fileno()))
            if not record.accepts(current, stream):
                return
            saved = self._read_unlocked()
            if saved is not None and saved.accepts(current, stream) and (saved.offset > record.offset):
                return
        self._write_unlocked(payload)

def capture(self, prepared: Checkpoint | None, stream: BinaryIO | None, revision: FileRevision | None) -> Checkpoint | None:
    if prepared is None or stream is None or revision is None:
        return None
    self._held = prepared if prepared.accepts(revision, stream) else None
    return self._held

def write(conn: sqlite3.Connection) -> Generation:
    goal = Generation.read_in(conn, reservation.goal_id)
    attempt = AttemptRecord.read_in(conn, reservation.attempt_id)
    if goal != Generation(reservation.goal_id, reservation.generation, ReservedGeneration(), reservation.attempt_id) or (attempt is None or attempt.reservation != reservation or (not attempt.phase.may_become(FailedAttempt()))):
        raise StaleAttemptError('Late failure cannot modify this goal generation.')
    attempt.advance(conn, FailedAttempt(), resolution=diagnostic)
    if observation is not None and attempt.phase.launched:
        record_observation(conn, reservation, observation)
    return goal.advance(conn, Generation(reservation.goal_id, reservation.generation, BlockedGeneration(), reservation.attempt_id))

def write(conn: sqlite3.Connection, digest: str) -> Generation:
    attempt = reservation.require_current(conn, ClaimedAttempt())
    attempt.advance(conn, SucceededAttempt(), progress_witness=progress_witness)
    current = Generation(reservation.goal_id, reservation.generation, ReservedGeneration(), reservation.attempt_id)
    return current.advance(conn, Generation(reservation.goal_id, reservation.generation + 1, ReadyGeneration(), None), digest=digest)

def write(conn: sqlite3.Connection) -> Generation:
    attempt = reservation.require_current(conn, ClaimedAttempt())
    attempt.advance(conn, SucceededAttempt(), progress_witness=witness)
    current = Generation(reservation.goal_id, reservation.generation, ReservedGeneration(), reservation.attempt_id)
    return current.advance(conn, Generation(reservation.goal_id, reservation.generation, CompletedGeneration(), reservation.attempt_id))

def write(conn: sqlite3.Connection) -> str:
    reservation.require_current(conn, ClaimedAttempt())
    row = GoalProviderUsage.one(conn, attempt_id=reservation.attempt_id, response_id=response_id)
    if row is not None:
        if row.usage_json != raw:
            raise ValueError('Provider response ID has different usage.')
    else:
        GoalProviderUsage(reservation.attempt_id, response_id, raw).insert(conn)
    return raw

def write(conn: sqlite3.Connection, digest: str) -> Generation:
    current = Generation.read_in(conn, goal_id)
    if current != Generation(goal_id, expected_generation, ReadyGeneration(), None):
        raise ReservationConflictError('Only an unreserved READY generation can be recovered.')
    return current.advance(conn, current, digest=digest)

def write(conn: sqlite3.Connection, digest: str) -> Generation:
    if Generation.one(conn, goal_id=goal_id) is not None:
        raise ReservationConflictError('Goal ID already has a ledger.')
    row = Generation(goal_id, 1, ReadyGeneration(), None, ready_digest=digest)
    row.insert(conn)
    return row

def write(conn: sqlite3.Connection) -> Reservation:
    current = Generation.read_in(conn, goal_id)
    if current != Generation(goal_id, expected_generation, ReadyGeneration(), None):
        raise ReservationConflictError('Goal generation is not ready or already reserved.')
    if not hmac.compare_digest(current.ready_digest, digest):
        raise UnresolvedAttemptError('Ready grant is stale or was never acknowledged.')
    AttemptRecord(attempt, ReservedAttempt(), None, None).insert(conn)
    current.advance(conn, Generation(goal_id, expected_generation, ReservedGeneration(), attempt.attempt_id))
    return attempt

def write(conn: sqlite3.Connection) -> LaunchPermit:
    current = reservation.require_current(conn, ReservedAttempt())
    current.advance(conn, ClaimedAttempt())
    return LaunchPermit(reservation)

def write(conn: sqlite3.Connection) -> Generation:
    goal = Generation.read_in(conn, goal_id)
    attempt = AttemptRecord.read_in(conn, attempt_id)
    if goal != Generation(goal_id, expected_generation, ReservedGeneration(), attempt_id) or (attempt is None or attempt.reservation.identity != GoalAttemptIdentity(goal_id, expected_generation, attempt_id) or (not attempt.phase.may_become(FailedAttempt()))):
        raise StaleAttemptError('Attempt changed before human abandonment decision.')
    GoalHumanDecision(goal_id, user_decision_id, expected_generation).claim(conn)
    attempt.advance(conn, FailedAttempt(), resolution=user_decision_id)
    return goal.advance(conn, Generation(goal_id, expected_generation, BlockedGeneration(), attempt_id))

def resume(self, goal_id: str, expected_generation: int) -> Generation:
    """Ordinary same-ID resume never resolves a reserved or blocked attempt."""
    current = self.snapshot(goal_id)
    if current is None or current.number != expected_generation:
        raise StaleAttemptError('Goal generation changed before resume.')
    if not current.lifecycle.ready or current.attempt_id is not None:
        raise UnresolvedAttemptError('Explicit attempt resolution is required before resume.')
    self.ready_grant(goal_id, expected_generation)
    return current

def write(conn: sqlite3.Connection, digest: str) -> Generation:
    current = Generation.read_in(conn, goal_id)
    if current != Generation(goal_id, expected_generation, ReadyGeneration(), None):
        raise UnresolvedAttemptError('Goal is not ready; an attempt may already be unresolved.')
    GoalHumanDecision(goal_id, user_decision_id, expected_generation).claim(conn)
    return current.advance(conn, Generation(goal_id, expected_generation + 1, ReadyGeneration(), None), digest=digest)

def write(conn: sqlite3.Connection, digest: str) -> Generation:
    current = Generation.read_in(conn, goal_id)
    if current != Generation(goal_id, expected_generation, BlockedGeneration(), attempt_id):
        raise UnresolvedAttemptError('Blocked attempt changed or is not resolved.')
    attempt = AttemptRecord.read_in(conn, attempt_id)
    if attempt is None or attempt.reservation.identity != GoalAttemptIdentity(goal_id, expected_generation, attempt_id) or (not isinstance(attempt.phase, FailedAttempt)):
        raise UnresolvedAttemptError('Only a blocked, recorded failure may be retried explicitly.')
    GoalHumanDecision(goal_id, user_decision_id, expected_generation).claim(conn)
    attempt.advance(conn, ResolvedAttempt(), resolution=user_decision_id)
    return current.advance(conn, Generation(goal_id, expected_generation + 1, ReadyGeneration(), None), digest=digest)

def write(conn: sqlite3.Connection) -> Generation:
    current = Generation.read_in(conn, goal_id)
    if current is None or current.number != expected_generation or current.attempt_id != attempt_id:
        raise StaleAttemptError('Goal generation or attempt changed before retirement.')
    attempt = AttemptRecord.read_in(conn, attempt_id) if attempt_id is not None else None
    if attempt_id is not None and (attempt is None or attempt.reservation.identity != GoalAttemptIdentity(goal_id, expected_generation, attempt_id)):
        raise StaleAttemptError('Unresolved goal has no matching attempt to retire.')
    if not current.lifecycle.permits_retirement(attempt.phase if attempt else None):
        raise StaleAttemptError('Goal or attempt is no longer eligible for retirement.')
    if attempt is not None:
        attempt.advance(conn, ResolvedAttempt(), resolution='goal cleared')
    return current.advance(conn, Generation(goal_id, expected_generation, CancelledGeneration(), attempt_id))

def bind(self, *, admission: int, turn_id: str, native_id: str, text: str) -> InputAttempt | None:
    self.require_not_cleared()
    return None

def _transition(self, target: type[StoredInput], **changes) -> StoredInput:
    values = {item.name: getattr(self, item.name) for item in fields(self)}
    return target(**values, **changes)

def bind(self, *, admission: int, turn_id: str, native_id: str, text: str) -> InputAttempt | None:
    if self.admission != admission:
        return None
    return self._transition(BoundUnknownInput, turn_id=turn_id, native_id=native_id, sent_digest=TextDigest.of(text))

