    claims = [claim for claim in cls.CLAIMS if re.search(f'\\b{re.escape(claim)}\\b', message.body, re.IGNORECASE)]
    if not claims or FileLine.scan(message.body) or cls.COMMANDS.search(message.body):
        return
    raise ValueError('Handoff message claims ' + ', '.join(claims) + ' without a file:line reference or a command in backticks as evidence.')

