@projected(view='wire', name='id')
def message_id(self) -> str:
    digest = hashlib.sha256(f'{self.sender}:{self.target}:{self.timestamp}:{self.body}'.encode()).hexdigest()[:12]
    return digest

@property
def display_metadata(self) -> dict:
    """Live messages carry no historical provenance decoration."""
    return {}

@classmethod
def from_wire(cls, data: Mapping) -> Message:
    from .bus_publication import PRIVATE_WIRE_FIELD
    public = {key: value for key, value in data.items() if key not in ('id', PRIVATE_WIRE_FIELD)}
    return FieldCodec.decode(cls, {'ts': 0.0, **public})

@classmethod
def from_committed_wire(cls, record: Mapping) -> Message:
    """One strict public-envelope boundary for full, indexed and cohort readers."""
    from .audience_manifest import MAX_WIRE_SEQ
    from .bus_publication import PRIVATE_WIRE_FIELD, _canonical, public_envelope_digest
    if not isinstance(record, Mapping):
        raise ValueError('Bus row is not an object.')
    public = {key: value for key, value in record.items() if key != PRIVATE_WIRE_FIELD}
    message = cls.from_wire(public)
    if _canonical(public) != _canonical(message.to_wire()):
        raise ValueError('Noncanonical public bus envelope.')
    if not 0 < message.seq <= MAX_WIRE_SEQ:
        raise ValueError('Bus sequence is outside the durable range.')
    public_envelope_digest(public)
    return message

def require_retained_admission(self, admission_after_seq: int) -> None:
    if self.claim_transition is None and self.seq > admission_after_seq:
        raise RelationViolationError('Unattested public initial exceeds the retained history boundary.')

@property
def response_policy(self) -> ResponsePolicy:
    """Typed response semantics without changing the stored target."""
    if self.notice or self.membership is not None:
        return InformationalPolicy.instance()
    if not (is_channel_target(self.target) or BuiltinChannel.lookup(self.target) is not None):
        return DirectPolicy.instance()
    if self.mentions:
        return MentionedOnlyPolicy.instance()
    if not self.sender_role.executable:
        return CollectivePolicy.instance()
    return InformationalPolicy.instance()

@property
def starts_turn(self) -> bool:
    """Whether every delivered recipient may start a turn."""
    return self.response_policy.starts_turn

def starts_turn_for(self, name: str, *, aliases: Mapping[str, str] | None=None) -> bool:
    """Whether this message enters one canonical recipient's model context."""
    channel = is_channel_target(self.target) or BuiltinChannel.lookup(self.target) is not None
    if not channel:
        return self.starts_turn
    return name in self.response_eligibility((name,), aliases=aliases).recipients

@property
def exact_reply_target(self) -> str:
    """The exact response destination owned by this opening message."""
    return self.target if is_channel_target(self.target) else self.sender

@property
def reply_target(self) -> str | None:
    """An external sender may receive an automatic live reply."""
    return None if self.sender_role.executable else self.exact_reply_target

def send(self, sender: str, target: str, body: str, type: Type[MessageKind]=InfoKind, *, notice: bool=False, claims: Sequence[FileClaimPath]=(), releases: Sequence[str | Path]=(), report: ChangeReport | None=None) -> str:
    """Declare a message and route it through the bus."""
    return self.send_message(sender, target, body, type, notice=notice, claims=claims, releases=releases, report=report).message_id

def send_message(self, sender: str, target: str, body: str, type: Type[MessageKind]=InfoKind, *, notice: bool=False, claims: Sequence[FileClaimPath]=(), releases: Sequence[str | Path]=(), task: TaskAttachment=NoTaskAttachment(), report: ChangeReport | None=None) -> Message:
    """Return one committed envelope, including optional guarded claims."""
    type.require_sendable()
    with guard_original_root_write(self.root), _store_lock(self._wire_lock_path):
        if sender not in self.registry:
            raise UnregisteredThreadError(f'Sender {sender!r} is not registered.')
        owner = self.registry.require(sender)
        if not owner.role.executable:
            raise RelationViolationError('Human messages require the explicit user-message operation.')
        message = Message(sender=owner.name, target=target, body=body, type=type, notice=notice, task=task, report=report, answers=self._answered_by(owner, target))
        if claims or releases:
            committed = self.bus.publisher.publish_claim_envelope(message, worktree=Path(owner.worktree), incarnation=str(owner.created_at), claims=claims, releases=releases)
        else:
            committed = self.bus.publisher.publish_ordinary(message)
    return committed

def _answered_by(self, owner: Thread, target: str) -> tuple[MessageReference, ...]:
    """What this owner's message to target answers among its running turn's inputs."""
    lease = owner.turn_lease
    if lease is None:
        return ()
    from .input_disposition import InputDispositions
    inputs = InputDispositions(self.root).in_turn(lease.turn_id)
    with self.bus.log.certified_read() as source:
        return inputs.answered_by(lease, source, self.registry.snapshot(), target)

def initialize_private_initial_protocol(self) -> str:
    """Initialize the private protocol on a fresh owner-only root."""
    with _store_lock(self._wire_lock_path):
        return self.bus.publisher.initialize_private_protocol()

def _user_identity_under_wire_lock(self, worktree: str) -> Thread:
    """Choose the durable USER identity while the caller holds the wire lock."""
    for thread in self._user_identities():
        return thread
    name, suffix = ('user', 2)
    while self.registry.name_reserved(name):
        name, suffix = (f'user-{suffix}', suffix + 1)
    thread = Thread(name, frozenset(), worktree, role=ThreadRole.USER)
    self.registry.register(thread)
    return thread

def _user_identities(self):
    """Derive existing humans from the original registered declarations."""
    return (thread for thread in self.registry.all_threads().values() if self.bus.reads.human(thread.role))

def user_identity(self, worktree: str) -> Thread:
    """One durable human sender, never an executor or a tag-derived agent role."""
    with _store_lock(self._wire_lock_path, shared=True):
        for thread in self._user_identities():
            return thread
    with _store_lock(self._wire_lock_path):
        return self._user_identity_under_wire_lock(worktree)

def send_user_message(self, target: str, body: str, *, worktree: str, task: TaskAttachment=NoTaskAttachment()) -> Message:
    """Cooperative local UI send, not cryptographic same-UID authentication."""
    with guard_original_root_write(self.root), _store_lock(self._wire_lock_path):
        user = self._user_identity_under_wire_lock(worktree)
        return self._publish_user_under_wire_lock(user, target, body, task)

def pin_user_constraint(self, recipient: str, subject: MessageReference, *, worktree: str, scope: TaskScopeSelection=CurrentTaskScopeSelection(), change: TaskChange=OriginalTaskChange()) -> Message:
    """Pin a certified original USER message; never replay it or lease a turn."""
    return self._pin_constraint(recipient, subject, HumanConstraintPin, worktree=worktree, scope=scope, change=change)

def pin_input_constraint(self, recipient: str, subject, *, worktree: str, scope: TaskScopeSelection=CurrentTaskScopeSelection(), change: TaskChange=OriginalTaskChange()) -> Message:
    """Pin the original input provenance, not a reconstruction of its text."""
    return self._pin_constraint(recipient, subject, NativeInputConstraintPin, worktree=worktree, scope=scope, change=change)

def approve_annotations(self, recipient, subject, *, worktree, per_hour, segments):
    from .working_memory_policy import AnnotationDisclosureGrant
    return self._pin_constraint(recipient, subject, AnnotationDisclosureGrant, worktree=worktree, scope=CurrentTaskScopeSelection(), change=OriginalTaskChange(), per_hour=per_hour, segments=segments)

def _pin_constraint(self, recipient, subject, declaration, *, worktree, scope, change, **declaration_options):
    with guard_original_root_write(self.root), _store_lock(self._wire_lock_path):
        user = self._user_identity_under_wire_lock(worktree)
        owner = self.registry.require(recipient)
        task = declaration(scope=scope.select_human(owner), subject=subject, source_user=user.incarnation, recipient=owner.incarnation, change=change, **declaration_options)
        return self._publish_user_under_wire_lock(user, owner.name, 'Pinned constraint from its original source', task, notice=True)

def _publish_user_under_wire_lock(self, user, target, body, task, *, notice=False):
    from .bus_publication import HumanOrigin
    return self.bus.publisher.publish_ordinary(Message(user.name, target, body, InfoKind, task=task, notice=notice), _human_origin=HumanOrigin(user.name, user.created_at, user.worktree))

def acknowledge_through(self, name: str, sequence: int) -> None:
    with _store_lock(self._wire_lock_path):
        self.bus.mark_delivered_through(self.registry.require(name).name, sequence)

@staticmethod
def reserve(*, owner, comms, autonomous):
    try:
        store = comms.goals.open_goal_store()
        admission = comms.registry.snapshot().admission_generations[owner.name]
        with _store_lock(comms._wire_lock_path):
            generation = store.require_generation(owner.goal.id)
            generation.lifecycle.require_ready()
            grant = comms.goals.ready_goal_grant_locked(owner, admission, generation)
            reservation = store.reserve(owner.goal.id, generation.number, ready_grant=grant)
            return store.claim_launch(reservation)
    except GoalAttemptError as error:
        if autonomous:
            return None
        raise RequestError.invalid_params({'reason': 'goal_attempt_unavailable', 'details': 'The goal has no launchable attempt. Inspect its state and use Retry for a failed attempt; no prompt was sent to Pi.'}) from error

def _check_owner(self, current: Thread | None, snapshot: RegistrySnapshot, canonical: str, source: TurnInputSource, text: str) -> None:
    if current is None:
        MissingTurnOwnerCheck().require_valid()
    OrdinaryOwnerCheck(expected=self.thread, current=current, registry=snapshot, canonical=canonical, admission=self.admission, turn=self.turn).require_valid()
    InputKeysCheck(source=source, text=text).require_valid()
    if source.accepted_id is None:
        return
    accepted = self.inputs.queued_inputs.get(self.session_id, {}).get(source.accepted_id)
    if accepted is None:
        for row in self.inputs.dispositions.read(source.keys).rows.values():
            row.require_not_cleared()
        MissingAcceptedInputCheck().require_valid()
    AcceptedInputCheck(receipt=accepted, current=current, admission=self.admission, input_id=source.accepted_id, keys=source.keys, accepted_source=self.inputs.following_sources.get(self.session_id, {}).get(source.accepted_id)).require_valid()

def native_start(self, public_id: str | None, native_id: str, sent_text: str) -> bool:
    source = self.source(public_id)
    return source.valid_keys(sent_text) and all((self.inputs.dispositions.started(key, turn_id=self.turn.value, native_id=native_id, text=sent_text) for key in source.keys))

def settle(self, session: TurnSession, transport_ok: bool) -> None:
    for cause in sorted(failures.TurnFailure.members_with(failures.TerminalFailure), key=lambda member: member.precedence, reverse=True):
        if cause.detected(session, transport_ok):
            self.record_failure(cause(cause.explanation(self)))

@classmethod
def capture(cls, document: RegistryDocument) -> RegistrySnapshot:
    """One live registry cut owns the index and all its source maps."""
    indexed: dict[str, Thread] = {}
    for thread in document.threads.values():
        incarnation = thread.incarnation.require_recorded()
        lookup = incarnation.lookup
        indexed[lookup] = thread
    return cls(threads=MappingProxyType(dict(document.threads)), statuses=MappingProxyType(dict(document.statuses)), last_seen=MappingProxyType(dict(document.last_seen)), aliases=MappingProxyType(dict(document.aliases)), owner_generations=MappingProxyType(dict(document.owners.generations)), admission_generations=MappingProxyType(dict(document.admissions.generations)), by_lookup=MappingProxyType(indexed))

async def settle(task: asyncio.Future) -> tuple[object, bool]:
    """Repeated caller cancellation cannot abandon a lock-held spawn."""
    cancelled = False
    while True:
        try:
            return (await asyncio.shield(task), cancelled)
        except asyncio.CancelledError:
            cancelled = True

@classmethod
def capture(cls, span, classifier, question: type[SpanQuestion], state, grant: MessageReference):
    return cls(span, classifier, QuestionVersion.current(question, state.owner_rules), FieldCodec.decode(ChoiceQuestionDefinition, question.declaration()), state, grant)

def capture(self, local: tuple) -> TickRevision:
    revisions = lambda paths: tuple((FileRevision.capture(path) for path in paths))
    return TickRevision(registry=revisions(self.registry), coordination=revisions(self.coordination), bus=revisions(self.bus), checkpoint=FileRevision.capture(self.checkpoint), other=(revisions(self.other), *local))

async def input_refused(self, session_id: str, input_id: str | None) -> None:
    if input_id is None:
        return
    source = self.following_sources.get(session_id, {}).pop(input_id, None)
    if source is not None:
        await self.emit_input_delivery_changed(session_id)
    item = self.queued_inputs.get(session_id, {}).pop(input_id, None)
    if item is not None:
        await item.not_started(self)
        await self.emit_queue_state(session_id)

def _notify_candidates(log: WireLog, through_bytes: int) -> None:
    from .candidate_maintenance import schedule_candidate_catchup
    schedule_candidate_catchup(log, through_bytes)

@property
def complete_boundary(self) -> int:
    """Last complete line inside this fixed physical cut, without reading history."""
    stream, revision = (self.stream, self.revision)
    if stream is None:
        if revision is not None:
            raise StaleRevision('Opened wire revision has no stream')
        return 0
    if revision is None or not revision.opened_by(stream):
        raise StaleRevision('Opened wire stream no longer contains its captured revision')
    position = stream.tell()
    try:
        end = revision.size
        if end:
            stream.seek(end - 1)
            if stream.read(1) == b'\n':
                return end
        while end:
            start = max(0, end - DEFAULT_BUFFER_SIZE)
            stream.seek(start)
            newline = stream.read(end - start).rfind(b'\n')
            if newline >= 0:
                return start + newline + 1
            end = start
        return 0
    finally:
        stream.seek(position)

def query_page_index[T](self, read: Callable[[BusPageIndex], T], *, empty: T) -> T:
    """Prepare/query this cut; source absence and index repair stay owned here."""
    if self.stream is None:
        return empty
    access = self.metadata.access
    with BusPageIndex(Path(self.stream.name)) as index:
        try:
            with index.prepared(self):
                return read(index)
        except StaleBusPageIndexError:
            access.require_append()
            index.invalidate()
        with index.prepared(self):
            return read(index)

def indexed_records(self, index: BusPageIndex, rows, *, before_offset: int):
    """Decode selected offsets through this original descriptor and byte cut."""
    if self.stream is None or not 0 <= before_offset <= self.boundary:
        raise RelationViolationError('Indexed read exceeds its opened wire cut')
    for row in rows:
        (message, size), = self.public_page_records(*index.record(self.stream, row, max_bytes=before_offset - row.offset), self.metadata)
        yield (message, size)

def remember_append_checkpoint(self, index: BusAppendIndex[Checkpoint], record: Checkpoint) -> None:
    """Keep a computed exact-cut value with this existing source resource."""
    if record.source != self.revision:
        raise ValueError('Computed append checkpoint belongs to another source cut')
    index.hold(record)
    self._append_checkpoints[index] = record

@property
def boundary(self) -> int:
    return self.revision.size if self.revision is not None else 0

def tail_bytes(self, max_bytes: int) -> tuple[bytes, int]:
    """Read trailing bytes from this fixed cut's retained descriptor."""
    if max_bytes < 0:
        raise ValueError('tail byte limit must be nonnegative')
    if self.stream is None:
        return (b'', 0)
    start = max(0, self.boundary - max_bytes)
    self.stream.seek(start)
    return (self.stream.read(self.boundary - start), start)

@staticmethod
def messages(record: Mapping) -> tuple[Message, ...]:
    from .errors import StoredHistoryUnreadable
    try:
        return WireRecord.public_from_wire(record).messages()
    except (TypeError, ValueError) as error:
        raise StoredHistoryUnreadable('Stored bus history cannot be decoded') from error

def appended_records(self, previous: FileRevision, previous_sequence: int) -> tuple[WireRecord, ...]:
    """Decode only bytes appended to the same opened source inode."""
    if self.stream is None or self.revision is None:
        raise RelationViolationError('Wire tail has no opened source')
    if previous.identity != self.revision.identity or previous.size > self.revision.size:
        raise RelationViolationError('Wire tail does not extend the settled source')
    self.stream.seek(previous.size)
    scan = WireScan(self.metadata, previous_sequence=previous_sequence)
    records = []
    while self.stream.tell() < self.boundary:
        raw = self.stream.readline(min(WireRecord.max_row_bytes + 1, self.boundary - self.stream.tell()))
        if not raw:
            break
        records.append(scan.read(raw))
    if scan.previous_sequence != self.metadata.last_seq:
        raise RelationViolationError('Wire tail does not reach its marker')
    if FileRevision.from_file(self.stream) != self.revision:
        raise RelationViolationError('Wire tail changed while it was read')
    return tuple(records)

def public_records(self, offset: int=0, *, before_offset: int | None=None) -> Iterator[tuple[Message, int]]:
    if self.stream is None:
        return
    boundary = self.boundary if before_offset is None else before_offset
    if not 0 <= offset <= boundary <= self.boundary:
        raise ValueError('Public read exceeds its opened source cut')
    self.stream.seek(offset)
    for record, raw_size in _iter_jsonl_stream(self.stream, boundary=boundary, label='wire snapshot'):
        yield from self.public_page_records(record, raw_size, self.metadata)

def messages_for_references(self, references):
    """Resolve exact public identities, including rows without a wake cohort."""
    messages = {message.reference: message for message, _ in self.public_records_for(frozenset((reference.seq for reference in references)), before_offset=self.complete_boundary)}
    if any((reference not in messages for reference in references)):
        raise RelationViolationError('Notification reference is not its original source')
    return tuple((messages[reference] for reference in references))

def public_records_for(self, sequences: frozenset[int], *, before_offset: int) -> Iterator[tuple[Message, int]]:
    """An uncertified cut must validate every original row, including silence."""
    if not 0 <= before_offset <= self.boundary:
        raise ValueError('Public read exceeds its opened source cut')
    if sequences:
        for message, size in self.public_records(before_offset=before_offset):
            if message.seq in sequences:
                yield (message, size)

@classmethod
def public_page_records(cls, record: Mapping, raw_size: int, metadata: WireMetadata) -> Iterator[tuple[Message, int]]:
    """Silent facts consume physical bytes, never message/display budgets."""
    for message in cls.messages(record):
        if has_private_wire_fields(record):
            yield (message, len(json.dumps(message.to_wire()).encode()) + 1)
        else:
            message.require_retained_admission(metadata.admission_after_seq)
            yield (message, raw_size)

@staticmethod
def messages(record: Mapping) -> tuple[Message, ...]:
    return WireRecord.certified_public_messages(record)

def public_records_for(self, sequences: frozenset[int], *, before_offset: int) -> Iterator[tuple[Message, int]]:
    """Resolve sparse changes through the same prepared index as page reads."""
    if not 0 <= before_offset <= self.boundary:
        raise ValueError('Public read exceeds its opened source cut')
    if not sequences:
        return

    def read(index):
        rows = (row for seq in sorted(sequences) for row in index.offsets(lower=seq - 1, upper=seq + 1, descending=False, targets=None, before_offset=before_offset))
        return tuple(self.indexed_records(index, rows, before_offset=before_offset))
    yield from self.query_page_index(read, empty=())

def read(index):
    rows = (row for seq in sorted(sequences) for row in index.offsets(lower=seq - 1, upper=seq + 1, descending=False, targets=None, before_offset=before_offset))
    return tuple(self.indexed_records(index, rows, before_offset=before_offset))

def capture(self, source, lookup: str) -> Iterator[CommittedDelivery]:
    """Copy selected bytes now; decode them only as the consumer advances."""
    return source.conversation_sources(lookup, self.predicate, self.parameters, limit=self.limit, ascending=self.ascending) if self.limit else iter(())

@classmethod
def frontier(cls, log: WireLog, lookup: str) -> int:
    """Read one conversation high-water without reconstructing a delivery."""
    if not log.path.exists() and (not log.metadata_path.exists()):
        return 0
    with log.certified_read() as source:
        return source.conversation_frontier(lookup)

@classmethod
def capture_many(cls, log: WireLog, lookup: str, requests: tuple[ConversationSourceWindowRequest, ...]) -> tuple[Iterator[CommittedDelivery], ...]:
    """Copy each selection from one source; consumers decode after release."""
    if not log.path.exists() and (not log.metadata_path.exists()):
        return tuple((iter(()) for request in requests))
    with log.certified_read() as source:
        return tuple((request.capture(source, lookup) for request in requests))

def __init__(self, path: Path):
    self.path = Path(path)
    self._append_indexes: list[BusAppendIndex] = []

def register_append_index(self, index: BusAppendIndex[Checkpoint]) -> BusAppendIndex[Checkpoint]:
    """Register one index owner for automatic capture with every opened cut."""
    if index.source_path != self.path:
        raise ValueError('Append index belongs to another bus')
    if index not in self._append_indexes:
        self._append_indexes.append(index)
    return index

@contextmanager
def locked(self, *, blocking: bool=True, max_bus_bytes: int | None=None, contention: StoreLockContention | None=None):
    """The existing canonical bus lock and durability read barrier."""
    with _store_lock(self.path, blocking=blocking, max_bus_bytes=max_bus_bytes, contention=contention) as lock:
        yield lock

@contextmanager
def certified_read(self, *, blocking: bool=True, contention: StoreLockContention | None=None):
    """Borrow the original source verified by the canonical reader barrier."""
    with _store_read_lock(self.path, blocking=blocking, contention=contention) as lock:
        with self._certified_source(lock) as source:
            yield source

async def read_certified_async(self, read: Callable):
    """Acquire cancellably, then consume the whole source in its worker.

        Return detached observations only. Verification and the callback share
        one resource thread; no SQLite connection crosses to the event loop.
        The worker closes physical custody before returning its result; result
        delivery must not keep a POSIX lock until the event loop resumes.
        Cancellation joins acquired work before the original descriptor closes.
        """
    from .private_bus_checkpoint import CheckpointNeedsRepair
    try:
        return await self._read_checked_under_lock(read, shared=True)
    except CheckpointNeedsRepair:
        return await self._read_checked_under_lock(read, shared=False)

def _read_certified(self, lock_file, platform, read, shared):
    with lock_file, _held_store_source(self.path, lock_file, platform, None, shared=shared) as lock:
        with self._certified_source(lock) as source:
            return read(source)

def record_context(self, manifest) -> None:
    """Append the context records chosen by the certified entry owner."""
    with self.locked() as lock:
        marker = self._private_marker_unlocked()
        for record in lock.certified_read().context_records(manifest):
            self._append_private_unlocked(marker, record.to_wire())

def context_manifest_page(self, name: str, registry, *, cursor=None, previous=()):
    from .private_bus_checkpoint import RecordedContextManifestSources
    return RecordedContextManifestSources.for_owner(self, name, registry, cursor=cursor, previous=previous)

def _assert_private_directory(self) -> None:
    """Require a nonredirectable, owned ancestry (root sticky /tmp permitted)."""
    if os.name != 'posix':
        raise RelationViolationError('Private bus requires POSIX ownership and modes.')
    if '..' in self.path.parts:
        raise RelationViolationError('Private bus directory ancestry is not trusted.')
    path = self.path.parent.absolute()
    while True:
        info = path.lstat()
        sticky_root = info.st_uid == 0 and bool(info.st_mode & stat.S_ISVTX)
        if not stat.S_ISDIR(info.st_mode) or info.st_uid not in {0, os.geteuid()} or (info.st_mode & 18 and (not sticky_root)):
            raise RelationViolationError('Private bus directory ancestry is not trusted.')
        if path == path.parent:
            break
        path = path.parent

def claim_projection(self) -> ClaimProjection:
    """Read current ownership from the canonical certified checkpoint."""
    with self.certified_read() as source:
        return source.claim_projection()

def _private_marker_unlocked(self) -> WireMetadata:
    self._assert_private_directory()
    if self.path.parent.lstat().st_uid != os.geteuid():
        raise RelationViolationError('Private bus directory is not owner-controlled.')
    sequence_path = self.metadata_path
    repair_path = self.path.with_name(self.path.name + '.corrupt')
    for path in (sequence_path, self.path, repair_path):
        if not path.exists() and (not path.is_symlink()):
            continue
        info = path.lstat()
        if not stat.S_ISREG(info.st_mode) or info.st_uid != os.geteuid() or stat.S_IMODE(info.st_mode) != 384:
            raise RelationViolationError('Private bus files require regular owner-only mode.')
    if not sequence_path.exists():
        raise RelationViolationError('Private bus writer has no durable protocol marker.')
    metadata = self.read_metadata_unlocked(required=True)
    if not metadata.private:
        raise RelationViolationError('Private bus writer has no durable protocol marker.')
    return metadata

def verified_records_unlocked(self, metadata: WireMetadata, *, on_row: Callable[[int, bytes, WireRecord], None] | None=None) -> Iterator[WireRecord]:
    """Entire strict stream; later corruption cannot certify an earlier append."""
    scan = WireScan(metadata)
    if not self.path.exists():
        return
    with self.path.open('rb') as stream:
        while True:
            offset = stream.tell()
            line = stream.readline(WireRecord.max_row_bytes + 1)
            if not line:
                break
            record = scan.read(line)
            if on_row is not None:
                on_row(offset, line, record)
            yield record

def read_delivery_cohort(self, wire_root_id: str, wire_seq: int) -> CommittedDelivery:
    """Bus-owned attestation of a committed initial row; no live re-routing."""
    if type(wire_seq) is not int or not 0 < wire_seq <= MAX_WIRE_SEQ:
        raise ValueError('wire_seq must be a positive SQLite-range integer.')
    with self.certified_read() as source:
        if wire_root_id != source.witness.root_id:
            raise RelationViolationError('Initial wire root does not match the bus marker.')
        return source.delivery(wire_seq)

def read_keyed_response(self, intent: PublicationIntents) -> Message | None:
    """Read-only exact receipt resolution; never append or repair an absent row."""
    with self.certified_read() as source:
        return source.keyed_receipt(intent)

def prepare_append_indexes(self) -> tuple[tuple[BusAppendIndex, AppendCheckpoint | None], ...]:
    """Read registered index candidates before taking any source locks."""
    return tuple(((index, index.prepare()) for index in self._append_indexes))

@staticmethod
def _snapshot_records(metadata, stream, boundary):
    scan = WireScan(metadata)
    while stream is not None and stream.tell() < boundary:
        raw = stream.readline(min(WireRecord.max_row_bytes + 1, boundary - stream.tell()))
        if not raw:
            break
        yield scan.read(raw)

@contextmanager
def _record_snapshot(self, *, need_sequence: bool=True) -> Iterator[tuple[int, Iterator[tuple[Message, int]]]]:
    """Explicit sequential history borrows the original opened byte boundary."""
    with self._opened_wire_snapshot(need_sequence=need_sequence) as opened:
        yield (opened.through, opened.public_records())

@contextmanager
def full_history_snapshot(self) -> Iterator[tuple[int, Iterator[Message]]]:
    """Open one fixed append boundary without retaining the complete wire."""
    with self._record_snapshot() as (through, records):
        yield (through, (message for message, _ in records))

def messages_for_references(self, references):
    with self._opened_wire_snapshot(need_sequence=False) as opened:
        return opened.messages_for_references(references)

def deliveries_for_references(self, references):
    """One canonical lock/certificate lifetime for a visible source window."""
    if not references:
        return ()
    with self.certified_read() as source:
        originals = source.references(references)
    return tuple(originals)

def latest_sequence(self) -> int:
    """Return the global high-water sequence without loading message bodies."""
    with _store_read_lock(self.path) as lock:
        return self._committed_sequence_unlocked(lock)

def _committed_sequence_unlocked(self, lock: StoreLock) -> int:
    """Read the committed cut from the resource acquired by this barrier.

        The certificate's global through_seq is not the addressed page's
        latest_source_seq or a marker reservation. The existing read barrier
        refuses private claim streams without their required certificate.
        """
    if lock.source is not None:
        return lock.certified_read().committed_sequence()
    return self.read_metadata_unlocked().last_seq

def _claim_marker_unlocked(self) -> WireMetadata | None:
    if self.path.name != 'bus.jsonl':
        return None
    metadata = self.read_metadata_unlocked()
    from .private_bus_checkpoint import certificate_enabled
    if certificate_enabled(self.path) and (not metadata.claims):
        raise RelationViolationError('Private checkpoint lacks its claim read barrier.')
    return metadata if metadata.claims else None

@property
def metadata_path(self) -> Path:
    return self.path.with_name('bus_meta.json')

def read_metadata_unlocked(self, *, required: bool=False) -> WireMetadata:
    """Read one marker inode under its leaf lock, independently of registry reads.

        Callers still own any required bus/registry transaction. Marker ownership
        is checked on the opened inode before this lock lets publication retire
        it; zero or multiple links are never accepted as owner-only storage.
        """
    with _store_lock(self.metadata_path, shared=True):
        try:
            descriptor = os.open(self.metadata_path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
        except FileNotFoundError as error:
            if required or self.metadata_path.is_symlink() or self.path.exists():
                raise RelationViolationError('Bus protocol marker is missing or redirected.') from error
            return WireMetadata()
        except OSError as error:
            raise RelationViolationError('Bus protocol marker is unreadable or redirected.') from error
        with os.fdopen(descriptor, encoding='utf-8') as source:
            info = os.fstat(source.fileno())
            if not stat.S_ISREG(info.st_mode):
                raise RelationViolationError('Bus protocol marker must be regular storage.')
            try:
                data = json.load(source, object_pairs_hook=unique_wire_object)
            except (ValueError, UnicodeError) as error:
                raise RelationViolationError('Bus protocol marker is malformed.') from error
        try:
            metadata = FieldCodec.decode(WireMetadata, data)
            if FieldCodec.encode(metadata) != data:
                raise ValueError('Noncanonical bus protocol marker')
        except (TypeError, ValueError) as error:
            raise RelationViolationError(f'Bus protocol marker is invalid: {error}') from error
        if metadata.private and (info.st_uid != os.geteuid() or stat.S_IMODE(info.st_mode) != 384 or info.st_nlink != 1):
            raise RelationViolationError('Private bus protocol marker is not owner-only')
        return metadata

def write_metadata_unlocked(self, metadata: WireMetadata) -> None:
    with _store_lock(self.metadata_path):
        _atomic_write_text(self.metadata_path, json.dumps(FieldCodec.encode(metadata), indent=2), fsync_parent=True)

def require_fresh_private_root_unlocked(self) -> None:
    self._assert_private_directory()
    root_info = self.path.parent.lstat()
    if root_info.st_uid != os.geteuid() or stat.S_IMODE(root_info.st_mode) != 448:
        raise RelationViolationError('Private bus directory must be owner-only.')
    repair = self.path.with_name(self.path.name + '.corrupt')
    if any((path.exists() or path.is_symlink() for path in (self.metadata_path, self.path, repair))):
        raise RelationViolationError('Existing unmarked bus data is read-only until its history is rewritten into the current source format.')

