def _bounded_inbox_response(messages: list[JsonObject], unresolved: list[JsonObject], review: JsonObject | None, result_file: str, *, ack: bool) -> JsonObject:
    """Project a saved inbox snapshot without changing any delivery or goal authority."""
    bounded: JsonObject = {'messages': [], 'acknowledged': 0, 'unresolved_inputs': [], 'complete': False, 'ackDeferred': ack, 'counts': {'messages': len(messages), 'unresolved_inputs': len(unresolved)}, 'result_file': result_file, 'instruction': 'The messages and unresolved_inputs arrays are omitted, not empty. The file is a complete public result snapshot, not current authority. Read it selectively with read offset/limit or a JSON query; do not dump the whole file into context. No messages were acknowledged. UNKNOWN inputs are unchanged. When standby_review.messages is present, its complete eligible messages and exact reviewed_inputs are inline; other review arrays are omitted with counts. Otherwise read the review from the file. Inspect the full relevant messages before passing their reviewed_inputs to comms_goal.'}
    if review is not None:
        review_summary: JsonObject = {'complete': False, 'counts': {key: len(review[key]) for key in ('messages', 'already_reviewed_inputs', 'excluded_inputs')}}
        bounded['standby_review'] = review_summary
        candidate = {**bounded, 'standby_review': {**review_summary, 'goal_id': review['goal_id'], 'wait_for': review['wait_for'], 'messages': review['messages'], 'reviewed_inputs': review['reviewed_inputs'], 'messages_complete': True}}
        if len(serialize_tool_output(candidate).encode('utf-8')) <= MAX_INLINE_OUTPUT_BYTES:
            return candidate
    return bounded

