def apply(self, comms: Comms, caller: ToolCaller) -> JsonObject:
    thread = self.thread
    target = self.target
    if target is not None:
        target = target.strip()
        if not target:
            raise ValueError('An inbox target cannot be empty.')
    goal_id = self.goal_id
    wait_for = self.wait_for
    if bool(goal_id) != bool(wait_for):
        raise ValueError('Provide goal_id and wait_for together for standby review.')
    review = comms.goals.goal_input_review(thread, goal_id, wait_for) if goal_id and wait_for else None
    inbox = comms.bus.inbox(thread, target)
    messages = [message.to_wire() for message in inbox]
    references = tuple((message.reference for message in inbox))
    unresolved = comms.goals.unresolved_inputs(thread)
    response: JsonObject = {'messages': messages, 'acknowledged': 0, 'unresolved_inputs': unresolved, **({'standby_review': review} if review is not None else {})}
    result_file = materialize_oversized_output(comms.root, response, inline_limit=MAX_INLINE_OUTPUT_BYTES - 64)
    if result_file is not None:
        return _bounded_inbox_response(messages, unresolved, review, str(result_file), ack=self.ack)
    response['acknowledged'] = comms.messaging.acknowledge(thread, references) if self.ack else 0
    return response

